import{_ as r,C as t,o,c as s,E as a,a2 as c}from"./chunks/framework.BOeh4kYD.js";const h="/joinwell52/assets/last-check-boundary-20260907/02-check-timing.en.png",v=JSON.parse('{"title":"The Check Passed. What Still Has to Hold When the Agent Acts?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"The Check Passed. What Still Has to Hold When the Agent Acts?","date":"2026-09-07","published_date":"2026-09-07","column":"open-source-engineering","category":"daily","article_type":"comparative-engineering-analysis","edition":"research-center","summary":"A source change before approval validation was refused. A change injected afterward reached the real copy executor. The comparison separates what a check binds from what keeps those facts true until execution.","cover":"/assets/last-check-boundary-20260907/02-check-to-effect-cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Controlled timing study complete; production concurrency and ingress reachability unverified","pageClass":"last-check-boundary-article"},"headers":[],"relativePath":"en/engineering/2026-09-07-check-to-effect-interval.md","filePath":"en/engineering/2026-09-07-check-to-effect-interval.md","lastUpdated":1788773549000}'),d={name:"en/engineering/2026-09-07-check-to-effect-interval.md"};function l(p,e,u,f,g,m){const i=t("ArticleCover"),n=t("ArticleTableScroll");return o(),s("div",null,[a(i,{image:"/assets/last-check-boundary-20260907/02-check-to-effect-cover-v1.png",kicker:"Open-source Engineering · Controlled Study",title:"The Check Passed. What Still Has to Hold When the Agent Acts?",summary:"A source change before approval validation was refused. A change injected afterward reached the real copy executor. The comparison separates what a check binds from what keeps those facts true until execution.",version:"2026-09-07",languageHref:"/zh/engineering/2026-09-07-check-to-effect-interval",languageLabel:"中文"}),a(n,{language:"en"}),e[0]||(e[0]=c('<p><a href="https://joinwell52-ai.github.io/joinwell52/assets/last-check-boundary-20260907/02-check-to-effect-cover-v1.png" target="_blank" rel="noreferrer">Open full-resolution cover</a></p><h1 id="the-check-passed-what-still-has-to-hold-when-the-agent-acts" tabindex="-1">The Check Passed. What Still Has to Hold When the Agent Acts? <a class="header-anchor" href="#the-check-passed-what-still-has-to-hold-when-the-agent-acts" aria-label="Permalink to &quot;The Check Passed. What Still Has to Hold When the Agent Acts?&quot;">​</a></h1><p>When a file operation is approved, its source contains A. Must it still contain A when the executor reads it?</p><p>That sounds like a filesystem detail, but agents routinely cross delays: approval, queuing, resource availability, and execution. If an object or condition changes along the way, what does an earlier successful check still permit?</p><p>A natural response is to check again, closer to execution. That is useful, but incomplete without another question: <strong>what was checked, and what can change between that check and the actual effect?</strong></p><p>We compared external proposals for start admission and exact file updates with a controlled timing experiment using CodeFlowMu’s real approval service and file executor. We did not reproduce a production concurrency incident. The post-check change was explicitly injected by the research code.</p><h2 id="_1-before-execution-can-refer-to-different-objects" tabindex="-1">1. “Before execution” can refer to different objects <a class="header-anchor" href="#_1-before-execution-can-refer-to-different-objects" aria-label="Permalink to &quot;1. “Before execution” can refer to different objects&quot;">​</a></h2><p>Paperclip is an open-source system for organizing agent work and runs. Its still-open <a href="https://github.com/paperclipai/paperclip/pull/12949" target="_blank" rel="noreferrer">PR #12949</a> proposes capacity admission after a run is claimed but before adapter startup. Observation and enforcement modes have different effects. This remains proposed functionality, not a delivered guarantee.</p><p>A capacity decision about starting a run is not authorization for every later file operation inside that run. Those operations have their own objects and conditions.</p><p><a href="https://github.com/github/github-mcp-server/pull/3232" target="_blank" rel="noreferrer">GitHub MCP Server Draft PR #3232</a> operates at another level: a particular repository file change. MCP exposes external operations as agent tools; this proposal binds an exact text update to expected branch and file-object identifiers.</p><p>The distinction is not a ranking of which project is safer. One concerns a run’s startup conditions; the other concerns a concrete repository mutation. Calling both a “gate” can hide their different responsibilities.</p><h2 id="_2-moving-the-source-change-across-the-check" tabindex="-1">2. Moving the source change across the check <a class="header-anchor" href="#_2-moving-the-source-change-across-the-check" aria-label="Permalink to &quot;2. Moving the source change across the check&quot;">​</a></h2><p>CodeFlowMu is a local multi-agent collaboration system we are developing. Its controlled file-operation requests include workspace and task identity, plus source and destination snapshots. Before execution, the current request is rebuilt and its digest is compared with the approved request. The digest is a fingerprint of the structured input, not a lock on the underlying file.</p><p>Earlier work had already shown that a changed destination can invalidate approval. Here we asked a different question: does changing source contents at different times produce the same outcome?</p><p>Using real components at commit <code>c008d9db91a21136fc61a4f60314e22db395d5d2</code>, we ran two copying scenarios. Both began with an existing destination and explicitly allowed overwrite. Overwrite was therefore not the disputed condition; the difference was when the source changed relative to digest validation.</p><table tabindex="0"><thead><tr><th>Comparison</th><th>When the source changed</th><th>Result, identical in both rounds</th><th>Filesystem effect</th></tr></thead><tbody><tr><td>Before validation</td><td>After approval, before rebuilding and checking the current request</td><td><code>APPROVAL_STALE</code>; execution callback entered zero times</td><td>Original destination preserved</td></tr><tr><td>After validation</td><td>Inside the research callback after approval validation, before calling the real executor</td><td>Recorded as succeeded; callback entered once</td><td>Destination received changed source contents</td></tr></tbody></table><p>The intervention in the second row is important. We did not observe a real user winning a race. After the approval service entered its execution callback, research code changed a synthetic source file, then called the existing product copy function. That point was deliberately controlled by the probe; we have not established equivalent control through an online interface.</p><p>The first row supports an existing protection. The second establishes behavior of the tested function composition under an injected sequence. Neither establishes who could change the source in a deployment, which ingress permits the same interleaving, or its likelihood.</p><p><img src="'+h+'" alt="E4 refuses a pre-check source change; E5 copies bytes changed by a post-check research injection"></p><p><em>Figure 1. E4/E5 timing comparison, two rounds each, with overwrite allowed in both. E5 explicitly injects the change after validation; it is not a reproduced production race. Source: formal controlled-study records; see the <a href="/joinwell52/en/research/evidence/2026-09-07-last-check-effect-boundary">evidence notes</a>.</em></p><p><a href="https://joinwell52-ai.github.io/joinwell52/assets/last-check-boundary-20260907/02-check-timing.en.png" target="_blank" rel="noreferrer">Open full-resolution figure</a></p><h2 id="_3-the-digest-was-correct—for-the-input-it-described" tabindex="-1">3. The digest was correct—for the input it described <a class="header-anchor" href="#_3-the-digest-was-correct—for-the-input-it-described" aria-label="Permalink to &quot;3. The digest was correct—for the input it described&quot;">​</a></h2><p>The approval service receives a current request and compares its digest with the approved one. On a match it records execution as in progress, then invokes the executor callback. The copy executor subsequently reads the source path.</p><p>In the first scenario, rebuilding the request observes the changed source snapshot. Validation rejects it before callback entry.</p><p>In the second, validation has already completed. The executor opens the same path, but the bytes there have changed. The approved source snapshot identifies <code>source-before</code>; the destination contains <code>source-after</code>, with a different digest. Both formal rounds produced that result.</p><p>There is no need to suppose a hash failure. The digest correctly describes the checked representation; it cannot prevent the mutable object behind that representation from changing afterward.</p><p>This is the time relationship studied under TOCTOU—time of check to time of use. Naming that relationship does not establish an exploitable race in a production path. <strong>A snapshot describes facts; it does not freeze them by itself.</strong></p><p>Likewise, publishing a destination through a temporary file and rename can address one class of write-publication problem. It does not independently establish that the source bytes are still the approved ones.</p><h2 id="_4-preconditions-need-a-corresponding-commit-rule" tabindex="-1">4. Preconditions need a corresponding commit rule <a class="header-anchor" href="#_4-preconditions-need-a-corresponding-commit-rule" aria-label="Permalink to &quot;4. Preconditions need a corresponding commit rule&quot;">​</a></h2><p>The GitHub proposal connects expected identifiers with commit construction and a non-forced branch update. That is more specific than a preflight warning. However, rejecting non-fast-forward updates is not proof of strict compare-and-swap behavior under every branch movement or rewind. The author also reports not running the complete Go suite in their environment; we performed no remote integration rerun. Its result already includes before/after identifiers. The downstream question is whether callers preserve and bind that receipt. <a href="https://github.com/github/github-mcp-server/pull/3232" target="_blank" rel="noreferrer">Proposal and limitations</a></p><p>Paperclip raises a separate applicability question: reattaching work already started is not the same as admitting a new start. Capacity should also correspond to the provider and model actually selected. Those issues appear in the <a href="https://github.com/paperclipai/paperclip/pull/12949" target="_blank" rel="noreferrer">proposal’s review discussion</a>; we did not independently rerun its recovery or database-concurrency scenarios.</p><p>These designs illuminate our experiment without validating it on our behalf. A Git branch update is not a local copy; capacity admission is not operation approval. The common question is narrower: <strong>do validation, execution, and commit still refer to the same object and conditions?</strong></p><h2 id="_5-investigate-the-remaining-interval-before-building-a-framework" tabindex="-1">5. Investigate the remaining interval before building a framework <a class="header-anchor" href="#_5-investigate-the-remaining-interval-before-building-a-framework" aria-label="Permalink to &quot;5. Investigate the remaining interval before building a framework&quot;">​</a></h2><p>Adding another check is not automatically sufficient: a change can occur after that check too, and different resources need different mechanisms.</p><p>First establish:</p><ol><li><strong>What was approved?</strong> A path, exact bytes, a version, or a combination?</li><li><strong>What does the effect consume?</strong> Bound data, or a fresh read of a mutable path or configuration?</li><li><strong>What preserves the condition through commit?</strong> Exclusive ownership, a conditional update, an immutable object, or only a prior observation?</li><li><strong>What happens when conditions change?</strong> Zero-effect refusal, partial effects, and insufficient evidence are different outcomes.</li></ol><p>A real-ingress experiment should include unchanged input, changes before checking, and changes after checking. Record source/destination digests, actual invocations, and receipts. Legitimate operations must still work. A refusal should be checked against resulting bytes, not merely an error message.</p><p>Our present result supports further investigation of the registered call path and filesystem competition. It does not authorize a general transaction engine or establish a live race vulnerability. Where a host, storage system, or executor already provides conditional-commit guarantees, investigate reuse before duplicating them.</p><p><strong>Reliable execution requires more than “we checked before acting.” It requires an explanation of why the checked conditions still hold when the effect occurs.</strong></p><h2 id="evidence-and-limits" tabindex="-1">Evidence and limits <a class="header-anchor" href="#evidence-and-limits" aria-label="Permalink to &quot;Evidence and limits&quot;">​</a></h2><p>This article uses E4/E5, twice each: four observations. Together with the companion article’s E0–E3, they make one twelve-observation formal batch. The <a href="/joinwell52/en/research/evidence/2026-09-07-last-check-effect-boundary">English evidence guide</a>, <a href="https://joinwell52-ai.github.io/joinwell52/assets/last-check-boundary-20260907/evidence/observations.json" target="_blank" rel="noreferrer">de-identified observations</a>, and <a href="/joinwell52/zh/research/evidence/2026-09-07-last-check-effect-boundary">Chinese guide</a> are publicly provided with this article.</p><p>The pilot also used no-overwrite in the timing cases, mixing two questions. The formal rerun allowed overwrite in both, isolating the timing comparison. Pilot records were retained but excluded from formal counts.</p><p>This is a Windows study of real product components with injected ordering—not live HTTP, panel, agent, multi-process contention, or remote GitHub mutation. Checking the records is distinct from rerunning the product. The writing stage performed no additional product experiment, code modification, independent QA, or repair.</p>',43))])}const w=r(d,[["render",l]]);export{v as __pageData,w as default};
